#include <string.h>
#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

enum { SR = 48000, N = SR / 2 };

static float l[N], r[N], lm[N], rm[N];

static void apply_bass_patch(wobble_t *s)
{
    wobble_set(s, W_SUB_LEVEL, 1.0f);
    wobble_set(s, W_CARRIER_LEVEL, 0.15f);
    wobble_set(s, W_CUTOFF, 1.0f);
    wobble_set(s, W_BASS_SPLIT, 0.285f);
}

static void render_blocks(wobble_t *s, float *ol, float *or, unsigned frames)
{
    for (unsigned p = 0; p < frames; ) {
        unsigned chunk = 256;
        if (p + chunk > frames)
            chunk = frames - p;
        wobble_render(s, ol + p, or + p, chunk);
        p += chunk;
    }
}

static void render_note(wobble_t *s, float *ol, float *or)
{
    wobble_note_on(s, 36, 100);
    render_blocks(s, ol, or, N);
    wobble_note_off(s, 36);
    render_blocks(s, ol, or, SR / 8);
}

static double corr_band(const float *xl, const float *xr, unsigned i0, unsigned i1, float lp_hz)
{
    double sx = 0, sy = 0, sxx = 0, syy = 0, sxy = 0;
    float lx = 0, ly = 0, ax = expf(-2.0f * (float)M_PI * lp_hz / SR);
    for (unsigned i = i0; i < i1; ++i) {
        lx = ax * lx + (1.0f - ax) * xl[i];
        ly = ax * ly + (1.0f - ax) * xr[i];
        sx += lx;
        sy += ly;
        sxx += lx * lx;
        syy += ly * ly;
        sxy += lx * ly;
    }
    double n = (double)(i1 - i0);
    double vx = sxx - sx * sx / n, vy = syy - sy * sy / n, cov = sxy - sx * sy / n;
    if (vx <= 0 || vy <= 0)
        return 1.0;
    return cov / sqrt(vx * vy);
}

static double side_rms(const float *xl, const float *xr, unsigned i0, unsigned i1, float hp_hz)
{
    double e = 0;
    float hp = 0, prev = 0;
    float a = expf(-2.0f * (float)M_PI * hp_hz / SR);
    for (unsigned i = i0; i < i1; ++i) {
        float d = xl[i] - xr[i];
        hp = a * (hp + d - prev);
        prev = d;
        e += hp * hp;
    }
    return sqrt(e / (double)(i1 - i0));
}

int main(void)
{
    wobble_t s, mono;
    int fails = 0;
    const unsigned i0 = 8000, i1 = 20000;
    float hz_def = wobble_bass_split_hz(0.285f);

    if (fabsf(wobble_bass_split_hz(0.0f) - 60.0f) > 0.5f
        || fabsf(wobble_bass_split_hz(1.0f) - 250.0f) > 1.0f)
        fails++, puts("FAIL split Hz endpoints");
    if (hz_def < 80.0f || hz_def > 100.0f)
        fails++, printf("FAIL default split %.2f Hz (want 80-100)\n", hz_def);
    if (fabsf(wobble_bass_split_alpha(0.0f) - 1.0f) > 0.02f
        || fabsf(wobble_bass_split_alpha(1.0f)) > 0.02f)
        fails++, puts("FAIL slope alpha endpoints");

    wobble_init(&s, (float)SR);
    apply_bass_patch(&s);
    wobble_set(&s, W_STEREO, 1.0f);
    render_note(&s, l, r);

    if (corr_band(l, r, i0, i1, 45.0f) < 0.995)
        fails++, printf("FAIL sub correlation %.4f\n", corr_band(l, r, i0, i1, 45.0f));
    if (side_rms(l, r, i0, i1, 150.0f) < 1e-5)
        fails++, puts("FAIL no stereo body side energy");

    wobble_init(&s, (float)SR);
    apply_bass_patch(&s);
    wobble_set(&s, W_STEREO, 1.0f);
    wobble_set(&s, W_BASS_SPLIT, 0.0f);
    render_note(&s, l, r);
    double side_lo = side_rms(l, r, i0, i1, 150.0f);

    wobble_init(&s, (float)SR);
    apply_bass_patch(&s);
    wobble_set(&s, W_STEREO, 1.0f);
    wobble_set(&s, W_BASS_SPLIT, 1.0f);
    render_note(&s, lm, rm);
    double side_hi = side_rms(lm, rm, i0, i1, 150.0f);
    if (fabs(side_lo - side_hi) < side_lo * 0.08)
        fails++, printf("FAIL split knob moves body width (side %.6g vs %.6g)\n", side_lo, side_hi);

    wobble_init(&s, (float)SR);
    apply_bass_patch(&s);
    wobble_set(&s, W_STEREO, 1.0f);
    render_note(&s, l, r);
    wobble_init(&mono, (float)SR);
    apply_bass_patch(&mono);
    wobble_set(&mono, W_STEREO, 0.0f);
    render_note(&mono, lm, rm);
    for (unsigned i = i0; i < i1; ++i) {
        if (fabsf(0.5f * (l[i] + r[i]) - lm[i]) > 2e-4f) {
            fails++, printf("FAIL mono downmix at %u\n", i);
            break;
        }
    }

    if (fails)
        printf("miami_stereo_split: %d FAILED\n", fails);
    else
        puts("PASS miami stereo split: sub centred, body width, knob law, downmix");
    return fails ? 1 : 0;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Host proof of pure gate + exact extracted common wrappers; no hardware calls."""
import argparse
import json
import os
from pathlib import Path
import subprocess
import tempfile

ROOT=Path(__file__).resolve().parents[3]


def function(source,signature):
    start=source.index(signature)
    left=source.index('{',start);depth=1;end=left+1
    while depth:
        depth+=(source[end]=='{')-(source[end]=='}');end+=1
    return source[start:end]


def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--output',type=Path,required=True);a=ap.parse_args()
    a.output.mkdir(parents=True,exist_ok=True)
    flags=['-std=c11','-Wall','-Wextra','-Werror','-pedantic','-I'+str(ROOT/'firmware/hal')]
    def run(args,**kw):
        r=subprocess.run(list(map(str,args)),text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,**kw)
        print(r.stdout,end='');r.check_returncode();return r.stdout
    test=Path(__file__).with_name('test_gate.c')
    run(['cc',*flags,test,'-o',a.output/'gate'])
    pure=run([a.output/'gate'])
    run(['cc',*flags,'-fsanitize=address,undefined','-fno-omit-frame-pointer','-no-pie',test,'-o',a.output/'gate-sanitized'])
    run([a.output/'gate-sanitized'],env=dict(os.environ,ASAN_OPTIONS='detect_leaks=0',UBSAN_OPTIONS='halt_on_error=1'))
    flash=(ROOT/'firmware/hal/fm1_flash.h').read_text()
    erase=function(flash,'static int fl_erase4k(')
    write=function(flash,'static int fl_write(')
    assert erase.index('fm1_capture_mutation_allowed')<erase.index('FL_PARK')<erase.index('fl_erase4k_ram')
    assert write.index('fm1_capture_mutation_allowed')<write.index('FL_PARK')<write.index('fl_prog_ram')
    # Compile the actual changed wrapper bodies, replacing only low-level HAL calls
    # with counters. Never compile/execute SPI/MMIO/asm source on the host.
    harness='''#include "fm1_capture_gate.h"
#include <assert.h>
#include <stdio.h>
static unsigned calls;
#define FL_PARK() 0
#define FL_UNPARK() ((void)0)
#define FL_FAR(x) (x)
static uint32_t irq_save(void){return 0;}
static void irq_restore(uint32_t f){(void)f;}
static int fl_erase4k_ram(uint32_t off,uint32_t *t){(void)off;(void)t;calls++;return 0;}
static int fl_prog_ram(uint32_t off,const uint8_t *p,uint32_t n,uint32_t *t)
{(void)off;(void)p;(void)n;(void)t;calls++;return 0;}
'''+erase+'\n'+write+'''
int main(void){uint32_t took=0;uint8_t bytes[300]={0};
assert(!fl_erase4k(0,&took));assert(!fl_write(0,bytes,300));assert(calls==3);
assert(!fm1_capture_gate_acquire(&fm1_capture_barrier,1,1,1));
assert(fl_erase4k(0,&took)==FM1_CAPTURE_BUSY);assert(calls==3);
assert(fl_write(0,bytes,300)==FM1_CAPTURE_BUSY);assert(calls==3);
assert(!fm1_capture_gate_current(&fm1_capture_barrier,1));
assert(!fm1_capture_gate_release(&fm1_capture_barrier,1));
assert(!fl_write(0,bytes,300));assert(calls==5);
assert(!fm1_capture_gate_acquire(&fm1_capture_barrier,2,1,1));
assert(!fl_write(0,bytes,0));assert(calls==5);
assert(fm1_capture_gate_current(&fm1_capture_barrier,2));
fm1_capture_handoff();assert(!fm1_capture_gate_current(&fm1_capture_barrier,2));
puts("PASS: exact common wrappers block raw calls; reset hook revokes; zero-length no mutation");return 0;}
'''
    with tempfile.TemporaryDirectory(prefix='mboot-wrapper-proof-') as tmp:
        p=Path(tmp)/'wrappers.c';p.write_text(harness)
        run(['cc',*flags,'-fsanitize=address,undefined','-no-pie',p,'-o',a.output/'wrappers'])
        wrappers=run([a.output/'wrappers'],env=dict(os.environ,ASAN_OPTIONS='detect_leaks=0',UBSAN_OPTIONS='halt_on_error=1'))
    system=(ROOT/'firmware/hal/fm1_sys.h').read_text()
    for sig in ['static void fm1_reboot(', 'static void fm1_enter_uboot(',
                'FM1_INLINE void fm1_core_reset(', 'FM1_INLINE void fm1_enter_update(']:
        body=function(system,sig)
        assert body.count('fm1_capture_handoff();')==1
        first=body.index('fm1_capture_handoff();')
        side=min(body.find(x) for x in ('__asm__','*(volatile') if x in body)
        assert first<side
    # No actual firmware acquisition call may sneak in under a disabled claim.
    for p in (ROOT/'firmware').rglob('*'):
        if p.suffix in ('.c','.h') and p.name!='fm1_capture_gate.h':
            assert 'fm1_capture_gate_acquire(' not in p.read_text(),str(p)
    result={'pure_gate':pure.strip(),'actual_wrappers':wrappers.strip(),'reset_boundaries':4,
            'platform':'OFF_NO_PRODUCTION_ACQUISITION','limits':['Host mocks never execute MMIO','Not complete multi-core exclusion or target qualification']}
    (a.output/'host-receipt.json').write_text(json.dumps(result,indent=2)+'\n')
    print(json.dumps(result,indent=2))


if __name__=='__main__':main()

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Independent read-only SMC User MIDI overflow/admission regression.

Extract actual production SMC functions, compile against an isolated synthetic
queue. No hardware, firmware compilation, MIDI writes or private inputs.
"""
import os
from pathlib import Path
import re
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[2]
SOURCE = Path(os.environ.get('SMC_SOURCE', ROOT / 'firmware/src/app/smc_mixer.c'))
PROTOCOL = Path(os.environ.get('SMC_PROTOCOL', ROOT / 'firmware/src/app/smc_protocol.h'))


def function(source, name):
    m = re.search(r'^[^\n]*\b' + re.escape(name) + r'\([^\n]*\)\s*\{', source, re.M)
    if not m:
        raise ValueError('Missing actual production function: ' + name)
    depth, end = 1, m.end()
    while depth:
        if end >= len(source):
            raise ValueError('Unterminated function: ' + name)
        depth += (source[end] == '{') - (source[end] == '}')
        end += 1
    return source[m.start():end]


HOST = r'''
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#define PROJ_BT_SMC_USER 32u
#define SMC_Q 32u
static volatile uint8_t smc_host_w, smc_host_r;
static struct { volatile uint32_t release_lost[4]; } smc_inputs[2];
#define smc_host_solo_release_lost smc_inputs[0].release_lost[1]
#define smc_pause_release_lost (smc_inputs[0].release_lost + 2)
static uint8_t smc_host_q[SMC_Q][3];
static struct { struct { uint8_t bt; } set; } proj;
'''

CASES = r'''
static unsigned cases, failed;
static uint32_t packet(uint8_t st, uint8_t a, uint8_t b)
{
    return 9u | ((uint32_t)st << 8) | ((uint32_t)a << 16) | ((uint32_t)b << 24);
}
static void scenario(const char *name, uint8_t st, uint8_t a, uint8_t b,
                     unsigned user, uint8_t w, uint8_t r,
                     unsigned accepted, uint8_t w_after, uint32_t release_lost)
{
    ++cases;
    memset(smc_host_q, 0xFE, sizeof smc_host_q);
    proj.set.bt = user ? PROJ_BT_SMC_USER : 0;
    smc_host_w = w;
    smc_host_r = r;
    smc_host_solo_release_lost = 0;
    unsigned ret = (unsigned)smc_midi_host(packet(st, a, b));
    unsigned wrote = w_after != w;
    int bad = ret != accepted || smc_host_w != w_after ||
              smc_host_solo_release_lost != release_lost;
    uint8_t i = w % SMC_Q;
    if (wrote) {
        bad |= smc_host_q[i][0] != st || smc_host_q[i][1] != a || smc_host_q[i][2] != b;
    } else {
        bad |= smc_host_q[i][0] != 0xFE || smc_host_q[i][1] != 0xFE || smc_host_q[i][2] != 0xFE;
    }
    if (bad) {
        ++failed;
        fprintf(stderr, "FAIL %s ret=%u/%u w=%u/%u lost=%u/%u queue=%02X-%02X-%02X\n",
                name, ret, accepted, smc_host_w, w_after,
                (unsigned)smc_host_solo_release_lost, (unsigned)release_lost,
                smc_host_q[i][0], smc_host_q[i][1], smc_host_q[i][2]);
    }
}
int main(void)
{
    /* Admission and ring fullness are distinct: return 1 can mean dropped. */
    scenario("solo-off-room", 0x8F, 8, 0, 1, 0, 0, 1, 1, 0);
    scenario("solo-off-last-free", 0x8F, 8, 0, 1, 31, 0, 1, 32, 0);
    scenario("solo-off-full", 0x8F, 8, 0, 1, 32, 0, 1, 32, 1);
    scenario("solo-vel0-full", 0x9F, 8, 0, 1, 32, 0, 1, 32, 1);
    scenario("solo-on-full", 0x9F, 8, 127, 1, 32, 0, 1, 32, 0);
    scenario("home-off-full", 0x8F, 6, 0, 1, 32, 0, 1, 32, 1);
    scenario("home-vel0-full", 0x9F, 6, 0, 1, 32, 0, 1, 32, 1);
    scenario("home-on-full", 0x9F, 6, 127, 1, 32, 0, 1, 32, 0);
    scenario("non-solo-off-full", 0x8F, 7, 0, 1, 32, 0, 1, 32, 0);
    scenario("non-solo-boundary-full", 0x8F, 16, 0, 1, 32, 0, 1, 32, 0);
    scenario("solo-end-full", 0x8F, 15, 0, 1, 32, 0, 1, 32, 1);
    scenario("user-cc-full", 0xBF, 40, 127, 1, 32, 0, 1, 32, 0);
    scenario("malformed-solo-note-full", 0x8F, 0x88, 0, 1, 32, 0, 0, 32, 0);
    scenario("malformed-solo-velocity-full", 0x8F, 8, 0x80, 1, 32, 0, 0, 32, 0);
    scenario("non-user-channel-full", 0x80, 8, 0, 1, 32, 0, 0, 32, 0);
    scenario("disabled-user-full", 0x8F, 8, 0, 0, 32, 0, 0, 32, 0);
    scenario("invalid-status-full", 0xAF, 8, 0, 1, 32, 0, 0, 32, 0);
    scenario("full-after-wrap", 0x8F, 8, 0, 1, 0, 224, 1, 0, 1);
    scenario("last-free-wrap", 0x8F, 8, 0, 1, 255, 224, 1, 0, 0);
    printf("SMC overflow/user-data7 source-exact: %u cases, %u failures\n", cases, failed);
    return failed ? 1 : 0;
}
'''


def main():
    src = (HOST + function(PROTOCOL.read_text(), 'smc_host_accept') + '\n'
           + function(SOURCE.read_text(), 'smc_is_solo_release') + '\n'
           + function(SOURCE.read_text(), 'smc_midi_host') + '\n' + CASES)
    with tempfile.TemporaryDirectory(prefix='smc-host-overflow-') as tmp:
        cfile = Path(tmp, 'regression.c')
        executable = Path(tmp, 'regression')
        cfile.write_text(src)
        flags = os.environ.get('SAN_FLAGS', '').split()
        command = [os.environ.get('CC', 'cc'), '-std=c99', '-O1', '-g',
                   '-Wall', '-Wextra', '-Werror', *flags,
                   str(cfile), '-o', str(executable)]
        subprocess.run(command, check=True)
        subprocess.run([str(executable)], check=True)


if __name__ == '__main__':
    main()

/* SPDX-License-Identifier: GPL-3.0-only */
/* Regress production SMC mapping against the keyboard's per-track mute contract.
 * Input consists of raw DAW MIDI messages. The radio/HCI path is bypassed.
 * The production project, engine, UI, queues, button map and LED map are used.
 * Hardware I/O and unused clip handlers are substitutes. No audio claim is made.
 */
#define main simulator_main
void smc_ui_cancel(void);
#include "../../host/x0x_host.c"
#undef main
#include <assert.h>

static uint8_t clip_mode;
uint8_t smk_clip_mode_on(void) { return clip_mode; }
int smk_ck_smc_turn(int n, int delta) { (void)n; (void)delta; return 0; }
int smk_ck_smc_nav(uint8_t note) { (void)note; return 0; }
int plat_ble_smc_send(const uint8_t *msg, uint8_t len)
{ (void)msg; (void)len; return 1; }
#ifndef SMC_MIXER_SOURCE
#define SMC_MIXER_SOURCE "app/smc_mixer.c"
#endif
#include SMC_MIXER_SOURCE

static void message(int status, int a, int b)
{
    const uint8_t raw[3] = {status, a, b};
    now_ms += 100;
    smc_ble_midi(raw, sizeof raw);
    smc_poll();
    smc_frame();
    assert((smc_rx_diag() >> 24) == 0);
}

static void setup(int mode, int bank)
{
    memset(&ui, 0, sizeof ui);
    memset(&smc, 0, sizeof smc);
    clip_mode = 0;
    boot();
    proj.set.bt = PROJ_BT_SMC_CENTRAL;
    smc_ble_link(1);
    smc_poll();
    if (!mode) smc_view(V_HOME, 0);
    else {
        smc_view(V_MIX, mode);
        ui.sel[mode - 1] = bank * 8;
        build_pages();
        assert(drum_mix_page() == mode - 1);
    }
    seq.mute = seq.vmute = 0;
    smc.solo = 0;
    engine_smc_solo(0);
    smc_frame();
}

static void continuous_probe(int mode, int bank, int strip)
{
    setup(mode, bank);
    pref_t r = smc_target(strip);
    pref_t k = smc_knob_target(strip);
    assert(r.kind == R_NONE ? k.kind == R_NONE : !smc_same(r, k));
    if (r.kind == R_NONE) return;
    if (mode) {
        pref_t expected = find_ref(mode == 1 ? T_909 : T_808, bank * 8 + strip, "Level");
        assert(expected.kind == R_ENG && expected.a == (mode == 1 ? T_909 : T_808));
        assert(expected.b == bank * 8 + strip);
        assert(smc_same(r, expected));
    }
    const x0x_param_t *d = pref_desc(r);
    const x0x_param_t *dk = pref_desc(k);
    pref_set(r, d->max / 2);
    /* Home CUT (and any other open-at-max default) must sit below the ceiling so a
     * +1 relative detent can prove the knob moved without touching the fader. */
    if (dk && dk->max)
        pref_set(k, dk->max / 2);
    smc_frame();
    int level = pref_get(r), before = pref_get(k);
    /* DAW K1 = b0 10 01. */
    message(0xB0, 16 + strip, 1);
    int after_knob = pref_get(k);
    assert(after_knob > before && pref_get(r) == level);
    /* First acquire the current target, then move the pitch-bend fader to 0. */
    message(0xE0 + strip, 0, smc_scaled(r));
    assert(smc.picked & (1u << strip));
    message(0xE0 + strip, 0, 0);
    assert(pref_get(r) == 0);
    printf("CONTINUOUS mode=%s bank=%d strip=%d target=%u/%u/%u/%u knob=%d->%d fader=%d->0 PASS\n",
           mode == 0 ? "MAIN" : mode == 1 ? "909" : "808", bank + 1, strip + 1,
           r.kind, r.a, r.b, r.c, before, after_knob, after_knob);
}


static void mute_regression(int mode, int bank, int strip)
{
    setup(mode, bank);
    int kit = mode - 1, track = bank * 8 + strip;
    int before_fx[3];
    for (int i = 0; i < 3; i++) {
        pref_t r = PR(R_ENG, T_FX, 0, i == 0 ? FX_RV_LEVEL : i == 1 ? FX_DL_LEVEL : FX_VOLUME);
        pref_set(r, 60 + i);
        before_fx[i] = pref_get(r);
    }
    /* A drum MIX page can show a kit that is not the selected part. */
    ui.part = 3;
    ui.sel[kit] = bank * 8 + 2;
    smc_frame();
    uint32_t expected = track < NDRUM ? 1u << (kit * NDRUM + track) : 0;
    message(0x90, 16 + strip, 127);
    assert(seq.vmute == expected);
    assert(seq.mute == 0);
    assert(smc.lit[16 + strip] == (track < NDRUM));
    for (int i = 0; i < 3; i++)
        assert(pref_get(PR(R_ENG, T_FX, 0, i == 0 ? FX_RV_LEVEL : i == 1 ? FX_DL_LEVEL : FX_VOLUME)) == before_fx[i]);
    assert(ui.sel[kit] == bank * 8 + 2 && ui.part == 3);
    message(0x90, 16 + strip, 127);
    assert(seq.vmute == 0 && seq.mute == 0 && smc.lit[16 + strip] == 0);
    if (track < NDRUM) {
        mute_track(kit, track);
        smc_frame();
        assert(seq.vmute == expected && smc.lit[16 + strip] == 1);
        mute_track(kit, track);
        smc_frame();
        assert(smc.lit[16 + strip] == 0);
        message(0x90, 24 + strip, 127);
        assert(ui.sel[kit] == track && ui.view == V_MIX);
        assert(smc.lit[24 + strip] == 1);
    } else {
        assert(smc_target(strip).kind == R_NONE);
        assert(smc_knob_target(strip).kind == R_NONE);
        message(0x90, 24 + strip, 127);
        assert(ui.sel[kit] == bank * 8 + 2 && smc.lit[24 + strip] == 0);
    }
    printf("PASS: %s bank %d M%d action, light and SELECT\n", mode == 1 ? "909" : "808", bank + 1, strip + 1);
}

static void main_regression(void)
{
    for (int strip = 0; strip < 8; strip++) {
        setup(0, 0);
        pref_t fx = strip < NPARTS ? NONE : PR(R_ENG, T_FX, 0,
            strip == 5 ? FX_RV_LEVEL : strip == 6 ? FX_DL_LEVEL : FX_VOLUME);
        int before = strip < NPARTS ? 0 : pref_get(fx);
        assert(strip < NPARTS || before > 0);
        message(0x90, 16 + strip, 127);
        assert(seq.vmute == 0 && smc.lit[16 + strip] == 1);
        if (strip < NPARTS) assert(seq.mute == MUTE_MASK[strip]);
        else assert(seq.mute == 0 && pref_get(fx) == 0);
        message(0x90, 16 + strip, 127);
        assert(seq.vmute == 0 && seq.mute == 0 && smc.lit[16 + strip] == 0);
        if (strip >= NPARTS) assert(pref_get(fx) == before);
    }
}

static void priority_regression(void)
{
    /* Keep the existing main-part mute behavior while menu or clip owns input. */
    for (int owner = 0; owner < 4; owner++) {
        setup(1, 0);
        if (owner == 0) ui.help = 1;
        if (owner == 1) ui.overlay = O_ASK;
        if (owner == 2) ui.overlay = O_LIST;
        if (owner == 3) clip_mode = 1;
        message(0x90, 17, 127);
        /* Help leaves drum MIX mutes working; confirmation parks the surface;
         * menu/clip fall through to whole-part mute instead. */
        assert(seq.vmute == (owner == 0 ? (1u << 1) : 0));
        assert(seq.mute == (owner >= 2 ? MUTE_MASK[1] : 0));
    }
    for (int kit = 0; kit < 2; kit++) {
        setup(kit + 1, 0);
        seq.vmute = 0xFFFFFFFFu;
        seq.mute = 0xFFFFFFFFu;
        smc_frame();
        for (int strip = 0; strip < 8; strip++) assert(smc.lit[16 + strip] == 1);
        message(0x90, 0x2F, 127);
        assert(ui.sel[kit] == 8);
        for (int strip = 0; strip < 8; strip++) {
            assert(smc.lit[16 + strip] == (strip < 3));
            assert(smc.lit[24 + strip] == (strip == 0));
        }
        message(0x90, 0x2E, 127);
        for (int strip = 0; strip < 8; strip++) assert(smc.lit[16 + strip] == 1);
        /* The owner-selected drum R/S layout follows the same visible bank. */
        setup(kit + 1, 1);
        message(0x90, 1, 127);
        assert(ui.part == kit && ui.sel[kit] == 9 && ui.rec);
        message(0x90, 9, 127);
        assert(smc_project_active() && smc.lit[9] == 1);
        message(0x80, 9, 0);
        assert(!smc_project_active() && smc.lit[9] == 0);
    }
}

int main(void)
{
    puts("Simulated raw DAW MIDI; production UI, engine, SMC queues and feedback; no radio/HCI or device claim.");
    main_regression();
    for (int strip = 0; strip < 8; strip++) continuous_probe(0, 0, strip);
    for (int mode = 1; mode <= 2; mode++)
        for (int bank = 0; bank < 2; bank++)
            for (int strip = 0; strip < 8; strip++) {
                mute_regression(mode, bank, strip);
                continuous_probe(mode, bank, strip);
            }
    priority_regression();
    puts("PASS: 22 active drum mute/light destinations, 10 inactive positions, 30 knob/fader writes, main mute/FX and ownership priorities.");
    return 0;
}

