    case R_BT: return &BT_P;
    case R_SMC_ROLE: return &SMC_ROLE_P;
    case R_SMC_MAP: return &SMC_MAP_P;
    case R_CKCH: return &CKCH_P;
    case R_CLKSRC: return &CLKSRC_P;
