    case R_BTNAME: {                                   /* read only: the name it advertises */
        static const char *nm[1];
        static const x0x_param_t d = {"NAME", 0, 0, nm};
        nm[0] = plat_ble_name()[0] ? plat_ble_name() : "-";
        return &d;
